void SystemProxyResolverAsyncWaiter::GetProxyForUrl(
    const ::blink::KURL& url, ::network::mojom::blink::ProxyListPtr* out_proxy_list, SystemProxyResolutionStatusPtr* out_status) {
  base::RunLoop loop;
  proxy_->GetProxyForUrl(
      std::move(url),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::network::mojom::blink::ProxyListPtr* out_proxy_list
,
             SystemProxyResolutionStatusPtr* out_status
,
             ::network::mojom::blink::ProxyListPtr proxy_list,
             SystemProxyResolutionStatusPtr status) {*out_proxy_list = std::move(proxy_list);*out_status = std::move(status);
            loop->Quit();
          },
          &loop,
          out_proxy_list,
          out_status));
  loop.Run();
}








